                "uuid": {
                    "type": "string",
                    "description": "uuid of this channel towards the middleware"
                },
                "identifier": {
                    "type": "string",
                    "description": "identifier of this channel from the meter. E.g. 1-0:1.8.0"
                },
                "api": {
                    "type": "string",
                    "enum": [
                        "volkszaehler",
                        "mysmartgrid",
                        "null"
