                    "type": "string",
                    "description": "secret key to use to talk to MySmartGrid api."
                },
                "type": {
                    "type": "string",
                    "enum": [
                        "device",
                        "sensor"
                    ],
                    "default": "device",
                    "description": "type of connected meter. Only needed for MySmartGrid api."
                },
                "scaler": {
                    "type": "integer",
                    "default": 1,
                    "description": "scaling factor to use. Only needed for MySmartGrid api."
