{
    "title": "A JSON Schema for apis.json, version 0.14",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "additionalProperties": false,
    "patternProperties": {
        "^X-": {
            "type": "object"
        }
    },
    "definitions": {
        "maintainers": {
            "description": "The person or organization responsible for maintaining the API",
            "required": [
                "name"
            ],
            "properties": {
                "name": {
                    "type": "string",
                    "description": "name",
                    "minLength": 5
                }
            },
            "additionalProperties": {
                "type": "string"
            }
        },
        "apis": {
            "description": "The description of the API",
            "oneOf": [
                {
                    "required": [
                        "name",
                        "description",
                        "image",
                        "baseURL",
                        "humanURL",
                        "properties",
                        "contact"
                    ],
                    "properties": {
                        "name": {
                            "type": "string",
                            "description": "name",
                            "minLength": 5
                        },
                        "description": {
                            "type": "string",
                            "description": "description of the API",
                            "minLength": 5
                        },
                        "image": {
                            "type": "string",
                            "description": "URL of an image representing the API"
                        },
                        "baseURL": {
                            "type": "string",
                            "pattern": "^(http)|(https)://(.*)$",
                            "description": "baseURL"
                        },
                        "humanURL": {
                            "type": "string",
                            "pattern": "^(http)|(https)://(.*)$",
                            "description": "humanURL"
                        },
                        "tags": {
                            "type": "array",
                            "items": {
                                "type": "string",
                                "minLength": 1
                            },
                            "description": "tags to describe the API"
                        },
                        "properties": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/urls"
                            },
                            "description": "URLs"
                        },
                        "contact": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/contact"
                            },
                            "description": "Contact to reach if questions about API"
                        },
                        "meta": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/metaInformation"
                            }
                        }
                    }
                }
            ]
        },
        "metaInformation": {
            "description": "Metadata about the API",
            "required": [
                "key",
                "value"
            ],
            "properties": {
                "key": {
                    "type": "string"
                },
                "value": {
                    "type": "string"
                }
            }
        },
