                    "type": "string",
                    "minLength": 1
                },
                "email": {
                    "type": "string",
                    "format": "email"
                },
                "organizationName": {
                    "type": "string",
                    "minLength": 1
                },
                "adr": {
                    "type": "string"
                },
                "tel": {
                    "type": "string",
                    "minLength": 1
                },
