                    "type": "string"
                },
                "X-github": {
                    "type": "string"
                },
                "photo": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                },
                "vCard": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                },
                "url": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                }
            }
        },
        "urls": {
